<template><AppLayout><div class="mx-auto max-w-3xl space-y-5"><RouterLink to="/supplier/accounts" class="text-sm text-primary-600">← {{ t('marketplace.accounts') }}</RouterLink><div v-if="loading" class="card p-6">{{ t('marketplace.loading') }}</div><div v-else-if="error && !account" class="card p-6" role="alert">{{ t('marketplace.loadFailed') }} <button class="text-primary-600 underline" @click="load">{{ t('marketplace.retry') }}</button></div><template v-else-if="account"><div class="card space-y-4 p-6"><h1 class="text-xl font-semibold">{{ account.name }}</h1><div class="grid gap-3 text-sm sm:grid-cols-2"><p>{{ t('marketplace.provider') }}: {{ account.platform }} / {{ account.type }}</p><div>{{ t('marketplace.reviewStatus') }}: <SupplierStatusBadge kind="review" :status="account.offer.review_status" /></div><div>{{ t('marketplace.healthStatus') }}: <SupplierStatusBadge kind="credential" :status="account.credential_status" /></div><p>{{ t('marketplace.currentRequests') }}: {{ account.current_concurrency }}</p></div><p v-if="readOnly" class="text-sm text-amber-600">{{ t('marketplace.readOnly') }}</p></div><section class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.usageSummary') }}</h2><div v-if="account.usage" class="grid gap-2 text-sm sm:grid-cols-2"><p>{{ t('marketplace.requests') }}: {{ account.usage.requests }}</p><p>{{ t('marketplace.inputTokens') }}: {{ account.usage.input_tokens }}</p><p>{{ t('marketplace.outputTokens') }}: {{ account.usage.output_tokens }}</p><p>{{ t('marketplace.consumerCharge') }}: {{ account.usage.consumer_charge }}</p><p>{{ t('marketplace.supplierNet') }}: {{ account.usage.supplier_net }}</p></div><p v-else class="text-sm text-gray-500">{{ t('marketplace.noUsage') }}</p></section><section class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.reviewHistory') }}</h2><ul v-if="account.reviews?.length" class="space-y-2 text-sm"><li v-for="(review, index) in account.reviews" :key="index"><SupplierStatusBadge kind="review" :status="review.status" /> {{ review.created_at }}<span v-if="review.reason"> — {{ review.reason }}</span></li></ul><p v-else class="text-sm text-gray-500">{{ t('marketplace.noReviews') }}</p></section><form class="card space-y-4 p-6" @submit.prevent="save"><h2 class="font-semibold">{{ t('marketplace.configuration') }}</h2><label class="block text-sm">{{ t('marketplace.accountName') }}<input v-model="name" required class="input mt-1 w-full" :disabled="readOnly || busy || saveUnknown" /></label><fieldset :disabled="readOnly || !provider || busy || saveUnknown"><legend class="text-sm">{{ t('marketplace.allowedModels') }}</legend><label v-for="model in provider?.models || account.offer.allowed_models" :key="model" class="mr-4 inline-flex items-center gap-1 text-sm"><input v-model="models" type="checkbox" :value="model" />{{ model }}</label></fieldset><AccountConcurrencyForm v-model="concurrency" :max="options?.max_supplier_concurrency || account.concurrency" :disabled="readOnly || !options || busy || saveUnknown" /><p v-if="!options" class="text-sm text-amber-600">{{ t('marketplace.optionsUnavailable') }}</p><div v-if="conflict" role="alert" class="space-y-2 text-sm text-amber-600"><p>{{ t('marketplace.versionConflict') }} <button type="button" class="underline" @click="refreshVersion">{{ t('marketplace.refreshVersion') }}</button></p><template v-if="conflictLatest"><p>{{ t('marketplace.latestConfiguration') }}: {{ conflictLatest.name }} · {{ conflictLatest.concurrency }} · {{ conflictLatest.offer.allowed_models.join(', ') }}</p><p>{{ t('marketplace.yourConfiguration') }}: {{ name }} · {{ concurrency }} · {{ models.join(', ') }}</p><button type="button" data-test="ack-detail-conflict" class="underline" @click="acknowledgeConflict">{{ t('marketplace.reviewedConfiguration') }}</button></template></div><p v-if="saveUnknown" role="alert" class="text-sm text-amber-600">{{ t('marketplace.operationUnknown') }} <button type="button" data-test="check-save" class="underline" :disabled="busy" @click="checkSave">{{ t('marketplace.checkStatus') }}</button> <button type="button" data-test="retry-save" class="underline" :disabled="busy" @click="retrySave">{{ t('marketplace.retrySameSave') }}</button></p><p v-if="error" role="alert" class="text-sm text-red-600">{{ t('marketplace.submitFailed') }}</p><button class="btn btn-primary" :disabled="readOnly || !options || !provider || busy || saveUnknown || conflict || !valid">{{ t('marketplace.save') }}</button></form><div class="card space-y-3 p-6"><h2 class="font-semibold">{{ t('marketplace.actions') }}</h2><p class="text-sm text-gray-500">{{ t('marketplace.probeExplanation') }}</p><div class="flex flex-wrap gap-2"><button v-if="['draft', 'rejected'].includes(account.offer.review_status) && !readOnly" class="btn btn-secondary" :disabled="busy || saveUnknown" @click="confirmAction('submit')">{{ t('marketplace.submitReview') }}</button><button v-if="account.offer.enabled && !readOnly" class="btn btn-secondary" :disabled="busy || saveUnknown" @click="confirmAction('pause')">{{ t('marketplace.pause') }}</button><button v-else-if="account.offer.review_status === 'approved' && !readOnly" class="btn btn-secondary" :disabled="busy || saveUnknown" @click="confirmAction('resume')">{{ t('marketplace.resume') }}</button><button v-if="!readOnly && ['api_key', 'apikey', 'oauth'].includes(account.type)" data-test="replace-credentials" class="btn btn-secondary" :disabled="busy || saveUnknown" @click="openCredentials">{{ t('marketplace.replaceCredentials') }}</button><button v-if="!readOnly" class="btn btn-secondary" :disabled="busy || saveUnknown" @click="performProbe">{{ t('marketplace.probe') }}</button><button v-if="!readOnly && account.offer.review_status !== 'revoked'" class="btn btn-secondary text-red-600" :disabled="busy || saveUnknown" @click="confirmAction('revoke')">{{ t('marketplace.revoke') }}</button></div><p v-if="probeResult" role="status" class="text-sm">{{ probeResult }}</p></div></template><AccountCredentialDialog v-if="credentialDialog && account" :account="account" :owner-id="auth.user?.id" @close="credentialDialog = false" @saved="credentialDialog = false; load()" /><BaseDialog :show="policyDialog" :title="t('marketplace.submitReview')" @close="policyDialog = false"><div class="space-y-3"><p>{{ t('marketplace.reviewPolicySummary', { fee: options?.fee_bps, hours: options?.hold_hours, version: options?.policy_version }) }}</p><p v-if="!reviewPricesAvailable" class="text-amber-600">{{ t('marketplace.priceUnavailable') }}</p><div v-for="price in reviewPrices" :key="`${price.model}-${price.group_name}-${price.price_version}`" class="rounded border p-3 text-sm"><p>{{ price.model }} · {{ price.public_model }} · {{ price.group_name }} · {{ price.price_version }} · {{ t('marketplace.rateMultiplier') }} {{ price.rate_multiplier }}</p><p v-for="tier in price.tiers" :key="tier.from_tokens">{{ t('marketplace.fromTokens') }} {{ tier.from_tokens }} — {{ t('marketplace.inputPrice') }} {{ tier.input_per_million }} / {{ t('marketplace.outputPrice') }} {{ tier.output_per_million }} / {{ t('marketplace.cacheReadPrice') }} {{ tier.cache_read_per_million }} / {{ t('marketplace.cacheWritePrice') }} {{ tier.cache_write_per_million }}</p></div><label class="flex gap-2"><input v-model="policyAccepted" data-test="accept-policy" type="checkbox" />{{ t('marketplace.acceptReviewPolicy') }}</label><p v-if="policyError" role="alert" class="text-red-600">{{ t('marketplace.policyChanged') }}</p></div><template #footer><button class="btn btn-secondary" @click="policyDialog = false">{{ t('common.cancel') }}</button><button data-test="submit-review" class="btn btn-primary" :disabled="busy || !policyAccepted || !reviewPricesAvailable" @click="submitReview">{{ t('marketplace.submitReview') }}</button></template></BaseDialog><ConfirmDialog :show="!!action" :title="t(`marketplace.${action || 'pause'}`)" :message="t(`marketplace.${action || 'pause'}Explanation`)" :danger="action === 'revoke'" @cancel="action = null" @confirm="perform" /></div></AppLayout></template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, nextTick, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import ConfirmDialog from '@/components/common/ConfirmDialog.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import SupplierStatusBadge from '@/components/supplier/SupplierStatusBadge.vue'
import AccountCredentialDialog from '@/components/supplier/AccountCredentialDialog.vue'
import AccountConcurrencyForm from '@/components/supplier/AccountConcurrencyForm.vue'
import { getAccount, getSupplierOptions, updateAccount, accountAction } from '@/api/supplier'
import { useWorkModeStore } from '@/stores/workMode'
import { useAuthStore } from '@/stores/auth'
import type { SupplierAccount, SupplierOptions } from '@/types/marketplace'
const { t } = useI18n(); const route = useRoute(); const store = useWorkModeStore(); const auth = useAuthStore(); const account = ref<SupplierAccount | null>(null); const options = ref<SupplierOptions | null>(null); const name = ref(''); const models = ref<string[]>([]); const concurrency = ref(1); const loading = ref(true); const error = ref(false); const conflict = ref(false); const busy = ref(false); const probeResult = ref(''); const action = ref<'submit' | 'pause' | 'resume' | 'revoke' | null>(null)
const conflictLatest = ref<SupplierAccount | null>(null); const credentialDialog = ref(false); const saveUnknown = ref(false); const submitted = ref<{ expected_version: number; name: string; concurrency: number; allowed_models: string[] } | null>(null)
onBeforeRouteLeave(() => !busy.value)
onBeforeRouteUpdate(() => !busy.value)
function beforeUnload(event: BeforeUnloadEvent) { if (busy.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', beforeUnload)
const policyDialog = ref(false); const policyAccepted = ref(false); const policyError = ref(false)
const reviewPrices = computed(() => (provider.value?.prices || []).filter(p => account.value?.offer.allowed_models.includes(p.model)))
const reviewPricesAvailable = computed(() => !!options.value?.policy_version && !!account.value?.offer.allowed_models.length && account.value.offer.allowed_models.every(m => reviewPrices.value.some(p => p.model === m && p.tiers.length > 0)))
const readOnly = computed(() => store.capabilities?.supplier_status === 'suspended' || store.capabilities?.marketplace_enabled === false); const provider = computed(() => options.value?.providers?.find(p => p.platform === account.value?.platform)); const valid = computed(() => !!name.value.trim() && models.value.length > 0 && Number.isInteger(concurrency.value) && concurrency.value > 0 && concurrency.value <= (options.value?.max_supplier_concurrency || 0))
watch([name, models, concurrency], () => { if (!loading.value) store.dirty = true }, { deep: true })
let loadGeneration = 0, disposed = false
function slot(owner: number | undefined, id: number) { return owner ? `supplier-config-operation:${owner}:${id}` : '' }
function context() { const owner = auth.user?.id, id = Number(route.params.id), generation = loadGeneration; return { owner, id, active: () => !disposed && auth.user?.id === owner && Number(route.params.id) === id && loadGeneration === generation } }
function clearSave(owner: number | undefined, id: number) { const key = slot(owner, id); if (key) sessionStorage.removeItem(key) }
async function load() { const generation = ++loadGeneration, owner = auth.user?.id, id = Number(route.params.id); const active = () => !disposed && generation === loadGeneration && auth.user?.id === owner && Number(route.params.id) === id; loading.value = true; error.value = false; account.value = null; saveUnknown.value = false; submitted.value = null; conflict.value = false; conflictLatest.value = null; if (!owner) { loading.value = false; store.dirty = false; return } try { const [a, o] = await Promise.all([getAccount(id), getSupplierOptions().catch(() => null)]); if (!active()) return; account.value = a; options.value = o; let saved: { expected_version: number; name: string; concurrency: number; allowed_models: string[] } | null = null; try { const key = slot(owner, id); const p = key ? JSON.parse(sessionStorage.getItem(key) || 'null') : null; if (p && Number.isSafeInteger(p.expected_version) && typeof p.name === 'string' && Number.isInteger(p.concurrency) && Array.isArray(p.allowed_models) && p.allowed_models.every((m: unknown) => typeof m === 'string')) saved = p } catch { /* Ignore invalid recovery metadata. */ } submitted.value = saved; saveUnknown.value = !!saved; name.value = saved?.name ?? a.name; models.value = [...(saved?.allowed_models ?? a.offer.allowed_models)]; concurrency.value = saved?.concurrency ?? a.concurrency; await nextTick(); if (active()) store.dirty = !!saved } catch { if (active()) error.value = true } finally { if (active()) loading.value = false } }
async function refreshVersion() { const c = context(); try { const result = await getAccount(c.id); if (c.active()) conflictLatest.value = result } catch { if (c.active()) error.value = true } }
function acknowledgeConflict() { if (!conflictLatest.value) return; clearSave(auth.user?.id, Number(route.params.id)); account.value = conflictLatest.value; submitted.value = null; saveUnknown.value = false; conflictLatest.value = null; conflict.value = false }
async function save() { if (!account.value || !valid.value || busy.value || saveUnknown.value || readOnly.value || conflict.value) return; const c = context(); busy.value = true; error.value = false; const snapshot = { expected_version: account.value.offer.version, name: name.value.trim(), concurrency: concurrency.value, allowed_models: [...models.value] }; submitted.value = snapshot; const key = slot(c.owner, c.id); if (key) sessionStorage.setItem(key, JSON.stringify(snapshot)); try { const result = await updateAccount(c.id, snapshot); if (!c.active()) return; account.value = result; clearSave(c.owner, c.id); submitted.value = null; store.dirty = false } catch (e) { if (!c.active()) return; const status = (e as { status?: number }).status; if (status === 409) conflict.value = true; else saveUnknown.value = true } finally { if (c.active()) busy.value = false } }
async function checkSave() { if (!account.value || !submitted.value || busy.value) return; const c = context(), snapshot = submitted.value; busy.value = true; try { const latest = await getAccount(c.id); if (!c.active()) return; if (latest.offer.version > snapshot.expected_version) { saveUnknown.value = false; if (latest.name === snapshot.name && latest.concurrency === snapshot.concurrency && [...latest.offer.allowed_models].sort().join('\0') === [...snapshot.allowed_models].sort().join('\0')) { account.value = latest; clearSave(c.owner, c.id); submitted.value = null; store.dirty = false } else { conflictLatest.value = latest; conflict.value = true; store.dirty = true } } } catch { /* Keep the unknown state until confirmed. */ } finally { if (c.active()) busy.value = false } }
async function retrySave() { if (!account.value || !submitted.value || busy.value || !saveUnknown.value) return; const c = context(), snapshot = submitted.value; busy.value = true; let inspect = false; try { const result = await updateAccount(c.id, snapshot); if (!c.active()) return; account.value = result; clearSave(c.owner, c.id); submitted.value = null; saveUnknown.value = false; store.dirty = false } catch (e) { if (c.active() && (e as { status?: number }).status === 409) inspect = true } finally { if (c.active()) busy.value = false } if (inspect && c.active()) await checkSave() }

async function openCredentials() { if (busy.value || saveUnknown.value) return; const c = context(), hadChanges = store.dirty; if (!await store.confirmLeave() || !c.active()) return; if (hadChanges && account.value) { name.value = account.value.name; models.value = [...account.value.offer.allowed_models]; concurrency.value = account.value.concurrency; await nextTick(); if (!c.active()) return; store.dirty = false } credentialDialog.value = true }
async function confirmAction(kind: 'submit' | 'pause' | 'resume' | 'revoke') { const c = context(), hadChanges = store.dirty; if (!await store.confirmLeave() || !c.active()) return; if (hadChanges && account.value) { name.value = account.value.name; models.value = [...account.value.offer.allowed_models]; concurrency.value = account.value.concurrency; await nextTick(); if (!c.active()) return; store.dirty = false } if (kind === 'submit') { try { const result = await getSupplierOptions(); if (!c.active()) return; options.value = result; policyAccepted.value = false; policyError.value = false; policyDialog.value = true } catch { if (c.active()) error.value = true } return } action.value = kind }
async function submitReview() { if (!account.value || !options.value?.policy_version || !policyAccepted.value || !reviewPricesAvailable.value || busy.value) return; const c = context(), version = account.value.offer.version, policyVersion = options.value.policy_version; busy.value = true; try { await accountAction(c.id, 'submit', version, policyVersion); if (!c.active()) return; policyDialog.value = false; busy.value = false; await load() } catch (e) { if (!c.active()) return; if ((e as { status?: number }).status === 409) { policyError.value = true; policyAccepted.value = false; try { const [latest, freshOptions] = await Promise.all([getAccount(c.id), getSupplierOptions()]); if (!c.active()) return; account.value = latest; options.value = freshOptions; name.value = latest.name; models.value = [...latest.offer.allowed_models]; concurrency.value = latest.concurrency; await nextTick(); if (c.active()) store.dirty = false } catch { if (c.active()) options.value = null } } else error.value = true } finally { if (c.active()) busy.value = false } }
async function perform() { if (!account.value || !action.value || busy.value) return; const c = context(), kind = action.value, version = account.value.offer.version; busy.value = true; try { await accountAction(c.id, kind, version); if (!c.active()) return; action.value = null; busy.value = false; await load() } catch (e) { if (!c.active()) return; action.value = null; if ((e as { status?: number }).status === 409) conflict.value = true; else error.value = true } finally { if (c.active()) busy.value = false } }
async function performProbe() { if (!account.value || busy.value) return; const c = context(), version = account.value.offer.version; busy.value = true; probeResult.value = ''; try { await accountAction(c.id, 'probe', version); if (c.active()) probeResult.value = t('marketplace.probeComplete') } catch { if (c.active()) probeResult.value = t('marketplace.probeFailed') } finally { if (c.active()) busy.value = false } }
watch(() => [route.params.id, auth.user?.id], () => { busy.value = false; credentialDialog.value = false; policyDialog.value = false; action.value = null; void load() }, { flush: 'sync' })
onMounted(load); onUnmounted(() => { disposed = true; loadGeneration++; window.removeEventListener('beforeunload', beforeUnload); store.dirty = false })
</script>
